```python
import os
import sys
import json

def count_lines_in_files(directory):
    if not os.path.isdir(directory) or not os.access(directory, os.R_OK):
        print("Error: Directory does not exist or is not accessible.")
        return

    line_counts = {}
    total_lines = 0

    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                file_path = os.path.relpath(os.path.join(root, file), directory)
                with open(os.path.join(root, file), 'r') as f:
                    lines = len(f.readlines())
                line_counts[file_path] = lines
                total_lines += lines

    line_counts['total'] = total_lines
    print(json.dumps(line_counts, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <directory>")
    else:
        count_lines_in_files(sys.argv[1])
